import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0033 — Un pacchetto sqlc per modulo e proprietà delle tabelle nel cloud","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0033-sqlc-per-module.md","filePath":"adr/0033-sqlc-per-module.md"}'),i={name:"adr/0033-sqlc-per-module.md"};function a(l,e,r,n,s,u){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="adr-0033-—-un-pacchetto-sqlc-per-modulo-e-proprieta-delle-tabelle-nel-cloud" tabindex="-1">ADR-0033 — Un pacchetto sqlc per modulo e proprietà delle tabelle nel cloud <a class="header-anchor" href="#adr-0033-—-un-pacchetto-sqlc-per-modulo-e-proprieta-delle-tabelle-nel-cloud" aria-label="Permalink to &quot;ADR-0033 — Un pacchetto sqlc per modulo e proprietà delle tabelle nel cloud&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §1.1, §2.7.3, §4.3 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-30</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§4.3 (moduli del cloud, «mai alle tabelle altrui», lint <code>depguard</code>/<code>go-arch-lint</code>), §2.7.3 (Excalidraw offline), V-08</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì (§4.3) → eccezioni dichiarate alla regola «mai alle tabelle altrui»; nuovo modulo <code>settings</code>; l&#39;albero di §4.3 guadagna <code>internal/&lt;modulo&gt;/&lt;modulo&gt;db</code></td></tr></tbody></table><p><strong>Aggiornamento 2026-11-02.</strong> <code>security.yml</code> è stato rimosso (ADR-0036); il gate offline di Excalidraw gira nella suite locale <code>yarn workspace @memobrain/web e2e:security</code>. Le eccezioni recepite nello spec sono quelle di <code>ownership_test.go</code> alla data (tra cui le letture di <code>jobs</code> su <code>file_revisions</code> e <code>shares</code>).</p><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Lo spec (§4.3) chiede che ogni modulo del cloud dipenda solo da <code>db</code>, <code>storage</code>, <code>audit</code>, <code>notify</code> e dalle interfacce degli altri moduli, <strong>mai dalle loro tabelle</strong>, con un lint che lo verifichi. Il codice aveva invece un unico pacchetto generato, <code>internal/db/dbgen</code>, con tutte le 165 query, e <code>.golangci.yml</code> non conteneva alcuna regola per i moduli. Una misura sul codice ha trovato 12 moduli su 15 che leggevano o scrivevano tabelle altrui. Tra le scritture incrociate:</p><ul><li><code>admin</code> cambiava stato, ruolo e quota in <code>users</code>;</li><li><code>sync</code> aggiornava <code>vaults</code>, <code>devices</code> e <code>shares</code> nel commit;</li><li><code>groups</code> cancellava <code>share_grants</code>;</li><li><code>jobs</code> e <code>privacy</code> toccavano quasi tutto.</li></ul><p>I tipi generati (<code>dbgen.Vault</code>, <code>dbgen.User</code>, <code>dbgen.Share</code>) attraversavano i moduli.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>Pacchetti.</strong> Ogni modulo ha un file di query, <code>internal/db/queries/&lt;modulo&gt;.sql</code>. sqlc lo genera in <code>internal/&lt;modulo&gt;/&lt;modulo&gt;db</code>: una voce per modulo in <code>sqlc.yaml</code>, con <code>omit_unused_structs</code>. <code>dbgen</code> non esiste più. Le query non usate sono state eliminate: <code>ListUserUsage</code>, <code>ListSettings</code>, <code>GetGrant</code>, <code>GetFileLive</code>, <code>GetUserBySub</code>, <code>GetUserStatus</code>.</p><p><strong>Transazioni.</strong> <code>db.WithTx</code> passa la <code>pgx.Tx</code>, e ogni modulo costruisce le proprie query (<code>&lt;modulo&gt;db.New(tx)</code>). Le funzioni che un modulo offre agli altri dentro una transazione prendono <code>db.DBTX</code> (pool o transazione), per esempio:</p><ul><li><code>blobs.AddRef</code> e <code>blobs.VaultBlob</code>;</li><li><code>quota.Charge</code>, <code>quota.UsedBytes</code> e <code>quota.Release</code>;</li><li><code>audit.Record</code>;</li><li><code>sharing.DeleteGrantsOfPrincipal</code>.</li></ul><p><strong>Accessi incrociati.</strong> Il proprietario espone wrapper sottili (<code>internal/&lt;modulo&gt;/exported.go</code>). Ogni wrapper esegue una query sul <code>DBTX</code> del chiamante. I tipi di parametri e righe sono alias (<code>users.User = usersdb.User</code>, <code>vaults.Vault</code>, <code>groups.Group</code>, …), così i valori passano invariati e il chiamante non importa mai il pacchetto db altrui. Se la chiamata diretta creerebbe un ciclo di import, si inietta un&#39;interfaccia dall&#39;applicazione: <code>groups.GrantRemover</code>, implementata da <code>sharing</code>.</p><p><strong>Nuovo modulo <code>settings</code>.</strong> È proprietario della tabella <code>settings</code>, cioè delle impostazioni di sistema e della revisione della configurazione. Prima sei moduli la leggevano direttamente; ora espongono le funzioni <code>Get</code>, <code>Int</code>, <code>Set</code>, <code>ConfigRevision</code> e <code>BumpConfigRevision</code>.</p><p><strong>Proprietà delle tabelle</strong> (<code>services/cloud/internal/db/ownership_test.go</code>):</p><table tabindex="0"><thead><tr><th>Modulo</th><th>Tabelle</th></tr></thead><tbody><tr><td><code>users</code></td><td><code>users</code>, <code>devices</code></td></tr><tr><td><code>vaults</code></td><td><code>vaults</code>, <code>vault_key_envelopes</code></td></tr><tr><td><code>sync</code></td><td><code>files</code>, <code>file_revisions</code></td></tr><tr><td><code>revisions</code></td><td><code>files</code>, <code>file_revisions</code> (co-proprietario: storico e retention)</td></tr><tr><td><code>quota</code></td><td><code>users</code> (solo le colonne di consumo, co-proprietario)</td></tr><tr><td><code>blobs</code></td><td><code>blobs</code>, <code>vault_blobs</code>, <code>uploads</code></td></tr><tr><td><code>sharing</code></td><td><code>shares</code>, <code>share_grants</code></td></tr><tr><td><code>groups</code></td><td><code>groups</code>, <code>group_members</code></td></tr><tr><td><code>configprofiles</code></td><td><code>config_profiles</code>, <code>config_profile_versions</code>, <code>config_assignments</code></td></tr><tr><td><code>audit</code></td><td><code>audit_log</code></td></tr><tr><td><code>export</code></td><td><code>export_jobs</code></td></tr><tr><td><code>admin</code></td><td><code>storage_snapshots</code></td></tr><tr><td><code>settings</code></td><td><code>settings</code></td></tr></tbody></table><p><strong>Eccezioni accettate.</strong> Sono elencate anche nel test, che fallisce per ogni accesso non dichiarato.</p><ul><li>Letture: <ul><li><code>admin</code>: aggregati della console (utenti, vault, dispositivi, audit, gruppi);</li><li><code>privacy</code>: export dei dati personali (GDPR art. 15);</li><li><code>notify</code>: fan-out degli eventi, perché <code>notify</code> non può dipendere dai moduli che pubblicano tramite lui;</li><li><code>blobs</code>: quali blob sono ancora referenziati e quali file vede un lettore condiviso;</li><li><code>sharing</code>: autorizzazione e radici delle condivisioni, perché <code>sync</code> dipende da <code>sharing</code>;</li><li><code>vaults</code>: manifest del vault, perché <code>sync</code> dipende da <code>vaults</code>;</li><li><code>configprofiles</code>: appartenenze ai gruppi;</li><li><code>groups</code>: nomi dei membri.</li></ul></li><li>Scritture: <ul><li><code>jobs</code>: manutenzione (raccolta dei blob, compattazione, purge, riconciliazione dei contatori);</li><li><code>privacy</code>: cancellazione dell&#39;account (GDPR art. 17), che cancella le righe dell&#39;account ovunque in un&#39;unica transazione.</li></ul></li><li>Tipi: <code>access.Vault</code> è un alias di <code>vaultsdb.Vault</code>. <code>access</code> è il vocabolario comune dei moduli che servono contenuto, e <code>vaults</code> dipende da <code>access</code>. È l&#39;unico import di un pacchetto db altrui, consentito per percorso in depguard.</li></ul><p><strong>Verifica.</strong> Due controlli complementari:</p><ul><li><code>depguard</code> in <code>.golangci.yml</code>, con una regola per ogni pacchetto db: nessun file fuori dal modulo può importarlo, salvo l&#39;eccezione di <code>access</code>. Gira in <code>task lint</code>.</li><li>Il test di proprietà, che analizza ogni file SQL (tabelle lette e scritte) rispetto alla mappa e alle eccezioni, e richiede un proprietario per ogni tabella creata dalle migrazioni. Gira in <code>task test</code>.</li></ul><p><strong>Gate offline di Excalidraw (stesso lavoro, §2.7.3).</strong> Un nuovo test Playwright, <code>web/e2e-security/excalidraw-offline.spec.ts</code>, gira nel job <code>web-security</code> di <code>security.yml</code>. Apre nel workbench web di produzione, con la CSP reale e il core vero, un disegno con testo cinese, e fallisce per qualsiasi richiesta esterna.</p><p>Il test ha trovato un difetto reale. Excalidraw elenca <code>esm.sh</code> come seconda sorgente di ogni font, e il browser andava a prendere da lì le 209 parti del font CJK Xiaolai: tutte bloccate dalla CSP, quindi il testo cinese non veniva mai reso con quel font. Il vecchio test desktop non lo vedeva perché il suo disegno non contiene testo.</p><p>La build (<code>copyExcalidrawAssets</code>, condivisa da desktop e web) ora riscrive quel fallback verso gli asset dell&#39;app. Se una versione futura del fork cambia quel testo, la build fallisce in modo esplicito.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><p><strong>Pacchetti per modulo con allowlist degli import esistenti</strong> — scartata. Fermava i nuovi accessi, ma consolidava quelli esistenti senza ridurli.</p></li><li><p><strong><code>dbgen</code> unico più un test sulle chiamate</strong> — scartata: non dava pacchetti per modulo e non toglieva i tipi condivisi.</p></li><li><p><strong>Nessuna eccezione</strong> (ogni lettura passa dal proprietario) — scartata per ora:</p><ul><li>avrebbe creato cicli (<code>sharing</code>↔<code>sync</code>, <code>vaults</code>↔<code>sync</code>, <code>notify</code>↔ moduli che pubblicano);</li><li>avrebbe spezzato le join di sola lettura in molte query.</li></ul><p>Le eccezioni sono poche e verificate.</p></li><li><p><strong><code>go-arch-lint</code></strong> (citato dallo spec) — non adottato. <code>depguard</code> copre già il vincolo sugli import e gira dentro golangci-lint, senza un altro tool da pinnare. Il controllo sulle tabelle richiedeva comunque un test sull&#39;SQL.</p></li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Una query nuova su una tabella altrui fallisce in <code>task test</code>, e un import di un pacchetto db altrui fallisce in <code>task lint</code>. Aggiungere un&#39;eccezione richiede di aggiornare la mappa del test e questo ADR.</li><li>Le query condivise da più moduli sono duplicate nei rispettivi file, quando una è un&#39;eccezione di lettura (<code>GetVault</code> in <code>jobs</code>, <code>GetShare</code> in <code>notify</code>, <code>GetFile</code> in <code>sharing</code> e <code>revisions</code>). Il prezzo è un po&#39; di SQL ripetuto.</li><li><code>jobs</code> ora chiama <code>admin.SnapshotStorage</code> e <code>quota.Release</code> invece di scrivere direttamente su <code>storage_snapshots</code> e <code>users</code>. <code>sync</code> passa da <code>vaults</code>, <code>users</code>, <code>quota</code> e <code>sharing</code> per le loro tabelle, sempre nella stessa transazione del commit.</li><li>Da rivedere: ridurre le eccezioni di scrittura di <code>jobs</code> e <code>privacy</code> spostando le operazioni nei proprietari (per esempio <code>vaults.Purge</code> e <code>blobs.Collect</code>).</li><li>L&#39;owner deve aggiornare §4.3 di <code>Specifications.md</code>: struttura dei pacchetti, eccezioni e modulo <code>settings</code>.</li></ul>',26)])])}const m=o(i,[["render",a]]);export{g as __pageData,m as default};
